        /// <summary>Makes this actor draw his weapon</summary>
        public Task DrawWeapon() => Dispatcher.CallAsync(self.Receiver, "DrawWeapon");

        /// <summary>
        /// **** For Debugging Movement Animations (not in release builds) ****
        /// Forces the movement direction on the actor
        /// afXAngle, afYAngle and afZAngle are in degrees
        /// </summary>
        public Task ForceMovementDirection(float afXAngle = 0.0f, float afYAngle = 0.0f, float afZAngle = 0.0f) => Dispatcher.CallAsync(self.Receiver, "ForceMovementDirection", new PapyrusArguments().Add(afXAngle).Add(afYAngle).Add(afZAngle));

        /// <summary>
        /// Forces the movement speed on the actor
        /// afSpeedMult is a speed multiplier based on the current max speeds
        /// - 0 -&gt; 1 Scales between 0 and the Walk speed
        /// - 1 -&gt; 2 Scales between Walk speed and Run Speed
        /// - 2 and above is a multiplier of the run speed (less 1.0 since Run is 2.0)
        /// </summary>
        public Task ForceMovementSpeed(float afSpeedMult) => Dispatcher.CallAsync(self.Receiver, "ForceMovementSpeed", new PapyrusArguments().Add(afSpeedMult));

        /// <summary>
        /// Forces the movement rotation speed on the actor
        /// Each component of the rotation speed is a multiplier following these rules:
        /// - 0 -&gt; 1 Scales between 0 and the Walk speed
        /// - 1 -&gt; 2 Scales between Walk speed and Run Speed
        /// - 2 and above is a multiplier of the run speed (less 1.0 since Run is 2.0)
        /// </summary>
        public Task ForceMovementRotationSpeed(float afXMult = 0.0f, float afYMult = 0.0f, float afZMult = 0.0f) => Dispatcher.CallAsync(self.Receiver, "ForceMovementRotationSpeed", new PapyrusArguments().Add(afXMult).Add(afYMult).Add(afZMult));

        /// <summary>
        /// Ramps the movement direction on the actor to the passed in value over the passed in time
        /// afXAngle, afYAngle and afZAngle are in degrees
        /// afRampTime is in seconds
        /// </summary>
        public Task ForceMovementDirectionRamp(float afXAngle = 0.0f, float afYAngle = 0.0f, float afZAngle = 0.0f, float afRampTime = 0.1f) => Dispatcher.CallAsync(self.Receiver, "ForceMovementDirectionRamp", new PapyrusArguments().Add(afXAngle).Add(afYAngle).Add(afZAngle).Add(afRampTime));

        /// <summary>
        /// Ramps the movement speed on the actor to the passed in value over the passed in time
        /// afSpeedMult is a speed multiplier based on the current max speeds
        /// - 0 -&gt; 1 Scales between 0 and the Walk speed
        /// - 1 -&gt; 2 Scales between Walk speed and Run Speed
        /// - 2 and above is a multiplier of the run speed (less 1.0 since Run is 2.0)
        /// afRampTime is in seconds
        /// </summary>
        public Task ForceMovementSpeedRamp(float afSpeedMult, float afRampTime = 0.1f) => Dispatcher.CallAsync(self.Receiver, "ForceMovementSpeedRamp", new PapyrusArguments().Add(afSpeedMult).Add(afRampTime));

        /// <summary>
        /// Ramps the movement rotation speed on the actor to the passed in value over the passed in time
        /// Each component of the rotation speed is a multiplier following these rules:
        /// - 0 -&gt; 1 Scales between 0 and the Walk speed
        /// - 1 -&gt; 2 Scales between Walk speed and Run Speed
        /// - 2 and above is a multiplier of the run speed (less 1.0 since Run is 2.0)
        /// afRampTime is in seconds
        /// </summary>
        public Task ForceMovementRotationSpeedRamp(float afXMult = 0.0f, float afYMult = 0.0f, float afZMult = 0.0f, float afRampTime = 0.1f) => Dispatcher.CallAsync(self.Receiver, "ForceMovementRotationSpeedRamp", new PapyrusArguments().Add(afXMult).Add(afYMult).Add(afZMult).Add(afRampTime));

        /// <summary>
        /// Sets the target movement direction on the actor
        /// afXAngle, afYAngle and afZAngle are in degrees
        /// </summary>
        public Task ForceTargetDirection(float afXAngle = 0.0f, float afYAngle = 0.0f, float afZAngle = 0.0f) => Dispatcher.CallAsync(self.Receiver, "ForceTargetDirection", new PapyrusArguments().Add(afXAngle).Add(afYAngle).Add(afZAngle));

        /// <summary>
        /// Sets the target movement speed on the actor
        /// afSpeedMult is a speed multiplier based on the current max speeds
        /// - 0 -&gt; 1 Scales between 0 and the Walk speed
        /// - 1 -&gt; 2 Scales between Walk speed and Run Speed
        /// - 2 and above is a multiplier of the run speed (less 1.0 since Run is 2.0)
        /// </summary>
        public Task ForceTargetSpeed(float afSpeed) => Dispatcher.CallAsync(self.Receiver, "ForceTargetSpeed", new PapyrusArguments().Add(afSpeed));

        /// <summary>
        /// Sets the target facing angle on the actor
        /// afXAngle, afYAngle and afZAngle are in degrees
        /// </summary>
        public Task ForceTargetAngle(float afXAngle = 0.0f, float afYAngle = 0.0f, float afZAngle = 0.0f) => Dispatcher.CallAsync(self.Receiver, "ForceTargetAngle", new PapyrusArguments().Add(afXAngle).Add(afYAngle).Add(afZAngle));

