        public Task<Form?> GetWornForm(int slotMask) => Dispatcher.CallAsync<Form?>(self.Receiver, "GetWornForm", new PapyrusArguments().Add(slotMask));

        /// <summary>returns the itemId for the item worn at the specified slotMask</summary>
        public Task<int> GetWornItemId(int slotMask) => Dispatcher.CallAsync<int>(self.Receiver, "GetWornItemId", new PapyrusArguments().Add(slotMask));

        /// <summary>
        /// returns the object currently equipped in the specified location
        /// 0 - left hand
        /// 1 - right hand
        /// 2 - shout
        /// </summary>
        public Task<Form?> GetEquippedObject(int location) => Dispatcher.CallAsync<Form?>(self.Receiver, "GetEquippedObject", new PapyrusArguments().Add(location));

        /// <summary>
