        [Obsolete("Uses the Papyrus virtual machine. Prefer Actor.DoReset3D(updateWeight: false).", DiagnosticId = "SF0004")]
        public Task QueueNiNodeUpdate() => Dispatcher.CallAsync(self.Receiver, "QueueNiNodeUpdate");

