        public Task RegenerateHead() => Dispatcher.CallAsync(self.Receiver, "RegenerateHead");

        /// <summary>equips item at the given slot</summary>
        public Task EquipItemEx(IForm item, int equipSlot = 0, bool preventUnequip = false, bool equipSound = true) => Dispatcher.CallAsync(self.Receiver, "EquipItemEx", new PapyrusArguments().Add(item).Add(equipSlot).Add(preventUnequip).Add(equipSound));

        /// <summary>equips item with matching itemId at the given slot</summary>
        public Task EquipItemById(IForm item, int itemId, int equipSlot = 0, bool preventUnequip = false, bool equipSound = true) => Dispatcher.CallAsync(self.Receiver, "EquipItemById", new PapyrusArguments().Add(item).Add(itemId).Add(equipSlot).Add(preventUnequip).Add(equipSound));

        /// <summary>unequips item at the given slot</summary>
        public Task UnequipItemEx(IForm item, int equipSlot = 0, bool preventEquip = false) => Dispatcher.CallAsync(self.Receiver, "UnequipItemEx", new PapyrusArguments().Add(item).Add(equipSlot).Add(preventEquip));

        /// <summary>
        /// Adds a headpart, if the type exists it will replace, must not be misc type
        /// Beware: This function also affects the ActorBase
        /// </summary>
        public Task ChangeHeadPart(HeadPart hPart) => Dispatcher.CallAsync(self.Receiver, "ChangeHeadPart", new PapyrusArguments().Add(hPart));

        /// <summary>
        /// Replaces a headpart on the loaded mesh does not affect ActorBase
