        public Task ReplaceHeadPart(HeadPart oPart, HeadPart newPart) => Dispatcher.CallAsync(self.Receiver, "ReplaceHeadPart", new PapyrusArguments().Add(oPart).Add(newPart));

        /// <summary>
        /// Visually updates the actors weight
        /// neckDelta = (oldWeight / 100) - (newWeight / 100)
        /// Neck changes are player persistent, but actor per-session
        /// Weight itself is persistent either way so keep track of your
        /// original weight if you use this for Actors other than the player
        /// DO NOT USE WHILE MOUNTED
        /// </summary>
        public Task UpdateWeight(float neckDelta) => Dispatcher.CallAsync(self.Receiver, "UpdateWeight", new PapyrusArguments().Add(neckDelta));

